{
  "type": "timeseries",
  "title": "Requests by status",
  "options": {
    "legend": {"displayMode": "table", "placement": "right",
               "calcs": ["mean", "max", "lastNotNull"]},
    "tooltip": {"mode": "multi", "sort": "desc"}
  },
  "fieldConfig": {
    "defaults": {
      "unit": "reqps",
      "custom": {
        "drawStyle": "line", "lineInterpolation": "linear", "lineWidth": 1,
        "fillOpacity": 20, "stacking": {"mode": "normal"},
        "spanNulls": false, "axisSoftMin": 0
      }
    },
    "overrides": [
      {"matcher": {"id": "byRegexp", "options": "5.."},
       "properties": [{"id": "color", "value": {"mode": "fixed", "fixedColor": "red"}}]}
    ]
  }
}

{
  "type": "stat",
  "title": "Error ratio",
  "fieldConfig": {
    "defaults": {
      "unit": "percentunit",
      "decimals": 2,
      "thresholds": {
        "mode": "absolute",
        "steps": [
          {"color": "green", "value": null},
          {"color": "orange", "value": 0.01},
          {"color": "red", "value": 0.05}
        ]
      },
      "mappings": [{"type": "value", "options": {"NaN": {"text": "no traffic"}}}]
    },
    "overrides": []
  }
}

{
  "type": "table",
  "title": "Targets",
  "targets": [{"refId": "A", "instant": true, "format": "table",
               "expr": "up"}],
  "transformations": [
    {"id": "organize", "options": {
      "excludeByName": {"Time": true, "__name__": true},
      "renameByName": {"Value": "status"}}}
  ],
  "fieldConfig": {
    "defaults": {},
    "overrides": [{
      "matcher": {"id": "byName", "options": "status"},
      "properties": [
        {"id": "custom.cellOptions", "value": {"type": "color-background"}},
        {"id": "mappings", "value": [{"type": "value", "options": {
          "0": {"text": "DOWN", "color": "red"},
          "1": {"text": "UP", "color": "green"}}}]}
      ]}]
  },
  "options": {"showHeader": true, "footer": {"show": true, "reducer": ["count"]}}
}

{
  "type": "table",
  "title": "Instances",
  "targets": [
    {"refId": "A", "instant": true, "format": "table",
     "expr": "sum by (instance) (rate(http_requests_total[5m]))"},
    {"refId": "B", "instant": true, "format": "table",
     "expr": "max by (instance) (process_resident_memory_bytes)"}
  ],
  "transformations": [
    {"id": "merge", "options": {}},
    {"id": "organize", "options": {
      "excludeByName": {"Time": true},
      "renameByName": {"Value #A": "req/s", "Value #B": "memory"}}},
    {"id": "sortBy", "options": {"sort": [{"field": "req/s", "desc": true}]}}
  ]
}

# Traces of the api service with a failing span
{ resource.service.name = "api" && span.http.status_code >= 500 }

# Slow checkout requests (any span over 2 seconds)
{ span.http.route = "/checkout" && duration > 2s }

# Traces where checkout calls payments (descendant relation)
{ span.http.route = "/checkout" } >> { resource.service.name = "payments" }

# More than 3 database spans in one trace (N+1 query smell)
{ span.db.system = "postgresql" } | count() > 3

# TraceQL metrics: request rate per route (needs metrics-generator)
{ resource.service.name = "api" } | rate() by (span.http.route)

terraform {
  required_providers {
    grafana = { source = "grafana/grafana", version = "~> 3.0" }
  }
}

provider "grafana" {
  url  = "https://grafana.example.com"
  auth = var.grafana_sa_token           # service account token, Admin role
}

resource "grafana_data_source" "prom" {
  type = "prometheus"
  name = "Prometheus"
  uid  = "prom-main"
  url  = "http://prometheus:9090"
  json_data_encoded = jsonencode({ timeInterval = "15s" })
}

resource "grafana_folder" "services" {
  title = "Services"
}

resource "grafana_dashboard" "api" {
  folder      = grafana_folder.services.uid
  config_json = file("${path.module}/dashboards/api-overview.json")
}

resource "grafana_contact_point" "api_slack" {
  name = "api-slack"
  slack {
    url   = var.slack_webhook
    title = "{{ .CommonLabels.alertname }}"
  }
}
